<form method="get" class="card-s mb-3 row g-2 align-items-end"><div class="col-md-6"><label class="form-label" for="subject">المادة</label><select class="form-select" id="subject" name="subject" data-autosubmit><?php foreach ($subjects as $id => $n): ?><option value="<?= (int)$id ?>" <?= $subject === (int)$id ? 'selected' : '' ?>><?= e($n) ?></option><?php endforeach; ?></select></div><div class="col-md-6 text-md-end"><a class="btn btn-outline-secondary" href="<?= url('school/lms') ?>">رجوع</a></div></form>
<?php if (!$subjects): ?><div class="alert alert-info">لا توجد مواد تدرّسها.</div><?php else: ?>
<div class="row g-3"><div class="col-lg-7"><div class="card-s"><h2 class="h6">الأسئلة (<?= count($questions) ?>)</h2><?php if (!$questions): ?><div class="empty-state">لا توجد أسئلة.</div><?php endif; ?>
  <?php foreach ($questions as $q): ?><div class="border-bottom py-2"><div class="d-flex gap-2"><span class="badge text-bg-info"><?= e($kinds[$q['kind']]) ?></span><span class="badge text-bg-secondary"><?= (float)$q['points'] ?> د</span><button class="btn btn-sm btn-outline-danger ms-auto" data-api="<?= url('api/v1/school/lms/bank/' . (int)$q['id']) ?>" data-method="DELETE" data-confirm="حذف السؤال؟"><i class="bi bi-trash"></i></button></div><div class="mt-1 math-content"><?= e($q['body']) ?></div><?= qimg($q['image_file_id'] ? (int)$q['image_file_id'] : null) ?>
    <?php if ($q['kind'] === 'mcq'): ?><ol class="small mb-0"><?php foreach ($q['options'] as $i => $o): ?><li class="<?= $i === $q['answer'] ? 'text-success fw-bold' : '' ?>"><span class="math-content"><?= e($o) ?></span><?= qimg(!empty($q['option_images'][$i]) ? (int)$q['option_images'][$i] : null, 'q-opt-img') ?></li><?php endforeach; ?></ol><?php elseif ($q['kind'] === 'true_false'): ?><small class="text-success">الإجابة: <?= $q['answer'] ? 'صح' : 'خطأ' ?></small><?php elseif ($q['kind'] === 'short'): ?><small class="text-success">المقبول: <?= e(implode(' / ', $q['answer'] ?: ['— (تصحيح يدوي)'])) ?></small><?php endif; ?></div><?php endforeach; ?></div></div>
  <div class="col-lg-5"><form class="card-s" id="qForm" method="post" action="<?= url('api/v1/school/lms/bank') ?>" data-ajax data-multipart data-reload enctype="multipart/form-data" novalidate><?= csrf_field() ?><input type="hidden" name="subject_id" value="<?= (int)$subject ?>"><h2 class="h6">سؤال جديد</h2>
    <div class="row g-2 mb-2"><div class="col-8"><select class="form-select" name="kind" id="qkind" aria-label="النوع"><?php foreach ($kinds as $k => $l): ?><option value="<?= $k ?>"><?= e($l) ?></option><?php endforeach; ?></select></div><div class="col-4"><input class="form-control" name="points" type="number" step="0.5" min="0.5" value="1" aria-label="الدرجة"></div></div>
    <div class="mb-2"><textarea class="form-control" name="body" rows="3" placeholder="نص السؤال (يمكن إدراج معادلات من «محرر المعادلات»)" data-math aria-label="السؤال"></textarea></div>
    <div class="mb-2"><label class="form-label small mb-1" for="qimg">صورة للسؤال (اختياري — PNG/JPG/WebP حتى 2MB)</label><input class="form-control form-control-sm" id="qimg" type="file" name="question_image" accept="image/png,image/jpeg,image/webp" data-preview="#qimgPrev"><img id="qimgPrev" class="q-img mt-2" alt="معاينة صورة السؤال" style="display:none"></div>
    <div data-kind="mcq"><div class="small fw-semibold mb-1">الخيارات <span class="text-muted fw-normal">— اختر الدائرة بجانب الخيار الصحيح؛ يمكن لكل خيار نص و/أو صورة</span></div><div id="optRows"></div>
      <button type="button" class="btn btn-sm btn-outline-secondary mb-2" id="addOpt"><i class="bi bi-plus-lg"></i> إضافة خيار</button></div>
    <div data-kind="true_false" class="d-none mb-2"><div class="form-check form-check-inline"><input class="form-check-input" type="radio" name="tf" value="true" id="tft" checked><label class="form-check-label" for="tft">صح</label></div><div class="form-check form-check-inline"><input class="form-check-input" type="radio" name="tf" value="false" id="tff"><label class="form-check-label" for="tff">خطأ</label></div></div>
    <div data-kind="short" class="d-none"><textarea class="form-control mb-2" name="accepted" rows="3" placeholder="الإجابات المقبولة (كل إجابة في سطر). اتركه فارغًا للتصحيح اليدوي" aria-label="المقبول"></textarea></div>
    <div data-kind="essay" class="d-none small text-muted mb-2">يُصحَّح يدويًا من المعلم.</div><button class="btn btn-primary" type="submit">إضافة السؤال</button></form></div></div><?php endif; ?>
